/* HD texture prefetch (FORK-053): see hd_texture_prefetch.h. */
#include "hd_texture_prefetch.h"

#include <algorithm>
#include <chrono>
#include <condition_variable>
#include <cstdio>
#include <deque>
#include <map>
#include <mutex>
#include <new>
#include <set>
#include <string>
#include <thread>
#include <tuple>

#include "third_party/picojson/picojson.h"

extern "C" {
/* Generated by port/fast3d/hd_texture_scope_embed.cmake from port/fast3d/texture_packs. */
extern const unsigned char hd_stage_prefetch_json[];
extern const size_t hd_stage_prefetch_json_size;
}

namespace hd_textures {
namespace prefetch {
namespace {

/* One image in a pack, whichever native keys share it. */
struct Id {
    std::string file;
    uint64_t header = 0;
    unsigned keep_rows = 0, of_rows = 0;
    bool operator<(const Id &o) const {
        return std::tie(file, header, keep_rows, of_rows) < std::tie(o.file, o.header, o.keep_rows, o.of_rows);
    }
};

Id id_of(const Entry &entry) { return {entry.file.generic_string(), entry.header, entry.keep_rows, entry.of_rows}; }

struct Job {
    Id id;
    Entry entry;
    uint32_t generation = 0;
};

/* Never destroyed: detached workers may still run while the process exits. */
struct Shared {
    std::mutex lock;
    std::condition_variable wake, idle;
    std::map<Key, Entry> downloads;      /* the download's entries, by native key */
    std::map<int, std::vector<Key>> learned; /* hd_stage_prefetch.json: other folders' keys a stage draws */
    uint32_t generation = 0;
    int stage = -1;                      /* the stage last requested */
    std::set<Id> wanted;                 /* its images */
    std::map<Id, Image> images;          /* read */
    std::map<Id, uint32_t> pending;      /* queued or being read, by generation */
    std::deque<Job> jobs;
    int workers = 0;
    std::chrono::steady_clock::time_point started;
    size_t requested = 0;
};
Shared &shared() {
    static Shared *s = new Shared;
    return *s;
}

/* LEVELID (src/bondconstants.h) -> the mission folder number in
 * hd_level_sources.json; the second missions at a place share its art. */
int mission_of(int stage) {
    switch (stage) {
        case 33: return 1;   /* Dam */
        case 34: return 2;   /* Facility */
        case 35: return 3;   /* Runway */
        case 36: case 43: return 4;  /* Surface, Surface II */
        case 9: case 27: return 5;   /* Bunker, Bunker II */
        case 20: return 6;   /* Silo */
        case 26: return 7;   /* Frigate */
        case 22: return 10;  /* Statue */
        case 24: return 11;  /* Archives */
        case 29: return 12;  /* Streets */
        case 30: return 13;  /* Depot */
        case 25: return 14;  /* Train */
        case 37: return 15;  /* Jungle */
        case 23: return 16;  /* Control */
        case 39: return 17;  /* Caverns */
        case 41: return 18;  /* Cradle */
        case 28: return 19;  /* Aztec */
        case 32: return 20;  /* Egyptian */
        default: return 0;   /* the multiplayer-only arenas have no folder of their own */
    }
}

void work() {
    Shared &s = shared();
    for (;;) {
        Job job;
        {
            std::unique_lock<std::mutex> guard(s.lock);
            s.wake.wait(guard, [&] { return !s.jobs.empty(); });
            job = std::move(s.jobs.front());
            s.jobs.pop_front();
            if (job.generation != s.generation || !s.wanted.count(job.id)) {
                if (job.generation == s.generation) s.pending.erase(job.id);
                s.idle.notify_all();
                continue;
            }
        }
        Image image;
        bool ok = false;
        try {
            ok = Pack::read(job.entry, image);
        } catch (const std::bad_alloc &) {
            ok = false;  /* the 32-bit build's address space: the renderer reads it itself later */
        }
        std::lock_guard<std::mutex> guard(s.lock);
        if (job.generation == s.generation) {
            s.pending.erase(job.id);
            if (ok && s.wanted.count(job.id)) s.images[job.id] = std::move(image);
        }
        s.idle.notify_all();
    }
}

/* "TTTTTTTT#F#S#PPPPPPPP", as GE_HD_USED writes it. */
bool parse_key(const std::string &text, Key &key) {
    unsigned texture = 0, format = 0, size = 0, palette = 0;
    if (std::sscanf(text.c_str(), "%8x#%u#%u#%8x", &texture, &format, &size, &palette) != 4) return false;
    key = Key{texture, palette, format, size};
    return true;
}

void load_learned(Shared &s) {
    static bool loaded = false;
    if (loaded) return;
    loaded = true;
    picojson::value doc;
    const std::string text(reinterpret_cast<const char *>(hd_stage_prefetch_json), hd_stage_prefetch_json_size);
    if (!picojson::parse(doc, text).empty() || !doc.is<picojson::object>()) return;
    const auto stages = doc.get<picojson::object>().find("stages");
    if (stages == doc.get<picojson::object>().end() || !stages->second.is<picojson::object>()) return;
    for (const auto &item : stages->second.get<picojson::object>()) {
        if (!item.second.is<picojson::array>()) continue;
        std::vector<Key> &keys = s.learned[std::atoi(item.first.c_str())];
        for (const auto &name : item.second.get<picojson::array>()) {
            Key key;
            if (name.is<std::string>() && parse_key(name.get<std::string>(), key)) keys.push_back(key);
        }
    }
}

/* As Pack::find: the exact key, then any palette. */
const Entry *download_for(const Shared &s, const Key &key) {
    auto it = s.downloads.find(key);
    if (it == s.downloads.end() && key.palette) it = s.downloads.find(Key{key.texture, 0, key.format, key.size});
    return it == s.downloads.end() ? nullptr : &it->second;
}

/* Under the lock: want the stage's images, drop the rest, queue what is missing. */
void rebuild(Shared &s) {
    load_learned(s);
    const std::vector<uint8_t> groups = groups_for_stage(s.stage);
    s.wanted.clear();
    std::map<Id, const Entry *> need;
    const auto want = [&](const Entry &entry) {
        const Id id = id_of(entry);
        s.wanted.insert(id);
        if (!s.images.count(id) && !s.pending.count(id)) need.emplace(id, &entry);
    };
    for (const auto &item : s.downloads) {
        if (std::find(groups.begin(), groups.end(), item.second.group) != groups.end()) want(item.second);
    }
    const auto learned = s.learned.find(s.stage);
    if (learned != s.learned.end()) {
        for (const Key &key : learned->second) {
            if (const Entry *entry = download_for(s, key)) want(*entry);
        }
    }
    for (auto it = s.images.begin(); it != s.images.end();) {
        it = s.wanted.count(it->first) ? std::next(it) : s.images.erase(it);
    }
    for (const auto &item : need) {
        s.jobs.push_back({item.first, *item.second, s.generation});
        s.pending[item.first] = s.generation;
    }
    s.requested = s.wanted.size();
    s.started = std::chrono::steady_clock::now();
    if (s.wanted.empty()) return;
    const unsigned cores = std::max(1u, std::thread::hardware_concurrency());
    const int threads = int(std::clamp(cores > 1 ? cores - 1 : 1u, 2u, 8u));
    for (; s.workers < threads; s.workers++) std::thread(work).detach();
    s.wake.notify_all();
    std::fprintf(stderr, "hd: prefetch: stage %d, %zu images (%zu to read)\n", s.stage, s.wanted.size(), need.size());
}
}  // namespace

std::vector<uint8_t> groups_for_stage(int stage) {
    if (stage == 90) return {kGroupTitle};  /* LEVELID_TITLE: the gunbarrel intro */
    if (stage < 0) return {};
    std::vector<uint8_t> groups{kGroupEffects};
    if (const int mission = mission_of(stage)) groups.push_back(uint8_t(mission));
    return groups;
}

void index_ready(std::map<Key, Entry> downloads, uint32_t generation) {
    Shared &s = shared();
    std::lock_guard<std::mutex> guard(s.lock);
    s.downloads = std::move(downloads);
    s.generation = generation;
    s.images.clear();
    s.pending.clear();
    s.jobs.clear();
    if (s.stage >= 0) rebuild(s);
    s.idle.notify_all();
}

void request_stage(int stage) {
    Shared &s = shared();
    std::lock_guard<std::mutex> guard(s.lock);
    s.stage = stage;
    rebuild(s);
}

bool wait(unsigned timeout_ms) {
    Shared &s = shared();
    std::unique_lock<std::mutex> guard(s.lock);
    const bool done = s.idle.wait_for(guard, std::chrono::milliseconds(timeout_ms), [&] { return s.pending.empty(); });
    if (s.requested) {
        size_t bytes = 0;
        for (const auto &item : s.images) bytes += item.second.rgba.size();
        const auto ms = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now()
                                                                              - s.started).count();
        std::fprintf(stderr, "hd: prefetch: stage %d, %zu of %zu images ready (%zu MB) %lld ms after the request%s\n",
                     s.stage, s.images.size(), s.requested, bytes >> 20, (long long) ms,
                     done ? "" : "; the rest are read in the background");
        s.requested = 0;
    }
    return done;
}

int stage() {
    Shared &s = shared();
    std::lock_guard<std::mutex> guard(s.lock);
    return s.stage;
}

bool own(int stage, const Entry &entry) {
    const std::vector<uint8_t> groups = groups_for_stage(stage);
    return std::find(groups.begin(), groups.end(), entry.group) != groups.end();
}

State find(const Entry &entry, Image &image) {
    Shared &s = shared();
    const Id id = id_of(entry);
    std::lock_guard<std::mutex> guard(s.lock);
    const auto it = s.images.find(id);
    if (it != s.images.end()) {
        /* Handed over, not copied (a 1024 px image is 4 MB): the GL texture
         * keeps it from here. Another key for the same image, or the image
         * again after the HD budget evicted it, is read in the background. */
        image = std::move(it->second);
        s.images.erase(it);
        return State::ready;
    }
    return s.pending.count(id) ? State::pending : State::none;
}
}  // namespace prefetch
}  // namespace hd_textures
